	tb.Helper()
	ctx, cancel := context.WithCancel(tb.Context())
	cancel()
	got, err := s.PartiallyNamed(ctx, fx.ID())
	if err == nil {
		tb.Skip("PartiallyNamed answered for a cancelled context, so this check has no error to inspect")
	}

	var zero string
	if got != zero {
		tb.Errorf("PartiallyNamed must return the zero value alongside an error: got %+v, want %+v (err %v)",
			got, zero, err)
	}
